# Baked in by SEA at generation time.
# DSN uses a scoped Crab role — NOT the SEA admin connection.
# Schema matches the database GRANTs for this role.
_DEFAULT_DSN = ""
_DEFAULT_DB_SCHEMA = ""
# The project's own env var for this database, if it has one — so the server
# reads the same connection string its CLI does instead of a second copy.
_DSN_ENV = "STRATEGY_DB_URL"
_PROJECT_JSON = Path(__file__).resolve().parent.parent / ".sea" / "project.json"


class NoDatabase(RuntimeError):
    """No connection string resolved. Raised instead of handing psycopg2 an
    empty DSN, which makes it connect to the LOCAL DEFAULT database — a
    different store than the one this server was generated for, with nothing
    to tell the caller."""


def _load_config() -> tuple[str, str]:
    """Resolve DSN and DB schema at runtime.

    Priority:
      1. CRAB_DATABASE_URL, then the project's own DSN env var if one was named
      2. connection.json crab_roles entry (updated whenever viz server regenerates Crab)
      3. Baked-in defaults (set at generation time)
    """
    for var in ("CRAB_DATABASE_URL", _DSN_ENV):
        if var and os.environ.get(var):
            return os.environ[var], _DEFAULT_DB_SCHEMA
    try:
        import json as _j
        conn_path = _PROJECT_JSON.parent / "connection.json"
        if conn_path.exists():
            conn = _j.loads(conn_path.read_text())
            primary_schema = _DEFAULT_DB_SCHEMA.split(",")[0].strip()
            entry = conn.get("crab_roles", {}).get(primary_schema, {})
            if entry.get("crab_dsn"):
                return entry["crab_dsn"], _DEFAULT_DB_SCHEMA
    except (OSError, ValueError):
        pass
    return _DEFAULT_DSN, _DEFAULT_DB_SCHEMA


DSN, DB_SCHEMA = _load_config()

