def _connect():
    if not DSN:
        raise NoDatabase(
            "no connection string: set CRAB_DATABASE_URL, or regenerate with --dsn. "
            "Refusing to connect with an empty DSN, which would open the local "
            "default database instead."
        )
    conn = psycopg2.connect(DSN)
    if DB_SCHEMA:
        with conn.cursor() as cur:
            cur.execute(f"SET search_path TO {DB_SCHEMA}")
    return conn


_ALLOWED_OPS = {"=", "!=", ">", "<", ">=", "<=", "LIKE", "ILIKE", "IN", "IS NULL", "IS NOT NULL"}


def _valid_columns(table: str) -> set[str]:
    """Return valid column names for a table from SCHEMA metadata."""
    if table not in SCHEMA_INFO:
        return set()
    return {f["name"] for f in SCHEMA_INFO[table]["fields"]}


async def query_table(
    table: str,
    filters: list[dict] | None = None,
    order_by: str = "id",
    order_dir: str = "ASC",
    limit: int = 20,
    include_related: bool = True,
) -> list[dict]:
    """Query a table with structured filters, validated ORDER BY, and FK joins."""
    from psycopg2 import sql as psql

    valid_cols = _valid_columns(table)
    select_cols = [f"{table}.*"]
    join_clauses = []

    if include_related and table in FK_JOINS:
        for join in FK_JOINS[table]:
            target = join["target_table"]
            fk = join["fk_field"]
            tcol = join["target_col"]
            join_clauses.append(
                f"LEFT JOIN {target} ON {table}.{fk} = {target}.{tcol}"
            )

    sql = f"SELECT {', '.join(select_cols)} FROM {table}"
    if join_clauses:
        sql += " " + " ".join(join_clauses)

    # Build parameterized WHERE from structured filters
    params = []
    where_parts = []
    for f in (filters or []):
        col = f.get("column", "")
        op = f.get("op", "").upper()
        val = f.get("value")
        if col not in valid_cols or op not in _ALLOWED_OPS:
            continue
        if op in ("IS NULL", "IS NOT NULL"):
            where_parts.append(f"{table}.{col} {op}")
        elif op == "IN":
            in_vals = [v.strip() for v in str(val).split(",") if v.strip()]
            if not in_vals:
                continue
            placeholders = ", ".join(["%s"] * len(in_vals))
            where_parts.append(f"{table}.{col} IN ({placeholders})")
            params.extend(in_vals)
        else:
            where_parts.append(f"{table}.{col} {op} %s")
            params.append(val)

    if where_parts:
        sql += " WHERE " + " AND ".join(where_parts)

    # Validated order_by — must be a known column
    if order_by not in valid_cols:
        order_by = "id"
    if order_dir.upper() not in ("ASC", "DESC"):
        order_dir = "ASC"
    sql += f" ORDER BY {table}.{order_by} {order_dir.upper()} LIMIT %s"
    params.append(min(limit, 100))

    with _connect() as conn:
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, params)
            rows = [dict(r) for r in cur.fetchall()]
            for row in rows:
                for k, v in row.items():
                    if not isinstance(v, (str, int, float, bool, type(None))):
                        row[k] = str(v)
            return rows


def _validate_fks(table: str, data: dict, conn) -> str | None:
    """Check that FK values in data exist in their target tables.

    Returns an error message string if validation fails, or None if OK.
    """
    joins = FK_JOINS.get(table, [])
    if not joins:
        return None
    with conn.cursor() as cur:
        for join in joins:
            fk_field = join["fk_field"]
            if fk_field not in data:
                continue
            val = data[fk_field]
            if val is None:
                continue  # nullable FK
            target_table = join["target_table"]
            target_col = join["target_col"]
            cur.execute(
                f"SELECT 1 FROM {target_table} WHERE {target_col} = %s LIMIT 1",
                [val],
            )
            if not cur.fetchone():
                return f"FK violation: {fk_field}={val} not found in {target_table}.{target_col}"
    return None


async def insert_row(table: str, data: dict) -> dict:
    """Insert a row and return the created record."""
    cols = list(data.keys())
    vals = list(data.values())
    placeholders = ", ".join(["%s"] * len(cols))
    col_names = ", ".join(cols)

    sql = f"INSERT INTO {table} ({col_names}) VALUES ({placeholders}) RETURNING *"

    with _connect() as conn:
        fk_err = _validate_fks(table, data, conn)
        if fk_err:
            return {"error": fk_err}
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, vals)
            conn.commit()
            row = dict(cur.fetchone())
            for k, v in row.items():
                if not isinstance(v, (str, int, float, bool, type(None))):
                    row[k] = str(v)
            return row


async def batch_insert(table: str, rows: list[dict]) -> list[dict]:
    """Insert multiple rows into a table in one transaction."""
    if not rows:
        return {"error": "No rows to insert"}
    results = []
    with _connect() as conn:
        # Validate all rows before inserting any
        for i, data in enumerate(rows):
            fk_err = _validate_fks(table, data, conn)
            if fk_err:
                return {"error": f"Row {i}: {fk_err}"}
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            for data in rows:
                cols = list(data.keys())
                vals = list(data.values())
                placeholders = ", ".join(["%s"] * len(cols))
                col_names = ", ".join(cols)
                sql = f"INSERT INTO {table} ({col_names}) VALUES ({placeholders}) RETURNING *"
                cur.execute(sql, vals)
                row = dict(cur.fetchone())
                for k, v in row.items():
                    if not isinstance(v, (str, int, float, bool, type(None))):
                        row[k] = str(v)
                results.append(row)
            conn.commit()
    return results


async def insert_with_children(table: str, data: dict, children: dict) -> dict:
    """Insert a parent row and its children in one transaction.

    The parent's new ID is auto-filled into each child row's FK field.
    children is a dict of {child_table: [row_dicts]}.
    """
    child_results = {}
    with _connect() as conn:
        # Validate parent FKs
        fk_err = _validate_fks(table, data, conn)
        if fk_err:
            return {"error": f"Parent: {fk_err}"}

        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            # Insert parent
            cols = list(data.keys())
            vals = list(data.values())
            placeholders = ", ".join(["%s"] * len(cols))
            col_names = ", ".join(cols)
            sql = f"INSERT INTO {table} ({col_names}) VALUES ({placeholders}) RETURNING *"
            cur.execute(sql, vals)
            parent_row = dict(cur.fetchone())
            parent_id = parent_row.get("id")

            # Insert children, auto-filling FK
            for child_table, child_rows in children.items():
                # Find the FK field that points to this parent
                fk_field = None
                for child_info in CHILDREN.get(table, []):
                    if child_info["child_table"] == child_table:
                        fk_field = child_info["fk_field"]
                        break
                if not fk_field:
                    child_results[child_table] = {"error": f"No FK from {child_table} to {table}"}
                    continue

                inserted = []
                for cdata in child_rows:
                    cdata[fk_field] = parent_id
                    # Validate non-parent FKs on child row
                    fk_err = _validate_fks(child_table, cdata, conn)
                    if fk_err:
                        child_results[child_table] = {"error": fk_err}
                        break
                    ccols = list(cdata.keys())
                    cvals = list(cdata.values())
                    cph = ", ".join(["%s"] * len(ccols))
                    ccn = ", ".join(ccols)
                    csql = f"INSERT INTO {child_table} ({ccn}) VALUES ({cph}) RETURNING *"
                    cur.execute(csql, cvals)
                    crow = dict(cur.fetchone())
                    for k, v in crow.items():
                        if not isinstance(v, (str, int, float, bool, type(None))):
                            crow[k] = str(v)
                    inserted.append(crow)
                else:
                    child_results[child_table] = inserted

            conn.commit()

    for k, v in parent_row.items():
        if not isinstance(v, (str, int, float, bool, type(None))):
            parent_row[k] = str(v)

    return {"parent": parent_row, "children": child_results}


async def update_row(table: str, id: int, data: dict) -> dict:
    """Update a row by ID and return the updated record."""
    if not data:
        return {"error": "No fields to update"}

    set_clause = ", ".join(f"{k} = %s" for k in data.keys())
    vals = list(data.values()) + [id]

    sql = f"UPDATE {table} SET {set_clause} WHERE id = %s RETURNING *"

    with _connect() as conn:
        fk_err = _validate_fks(table, data, conn)
        if fk_err:
            return {"error": fk_err}
        with conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
            cur.execute(sql, vals)
            conn.commit()
            row = cur.fetchone()
            if not row:
                return {"error": f"No row with id={id} in {table}"}
            row = dict(row)
            for k, v in row.items():
                if not isinstance(v, (str, int, float, bool, type(None))):
                    row[k] = str(v)
            return row


async def delete_row(table: str, id: int) -> dict:
    """Delete a row by ID."""
    with _connect() as conn:
        with conn.cursor() as cur:
            cur.execute(f"DELETE FROM {table} WHERE id = %s RETURNING id", [id])
            conn.commit()
            deleted = cur.fetchone()
            if not deleted:
                return {"error": f"No row with id={id} in {table}"}
            return {"deleted": True, "table": table, "id": id}


async def get_schema_info(table: str | None = None) -> dict:
    """Return schema information."""
    if table:
        info = SCHEMA_INFO.get(table)
        if not info:
            return {"error": f"Unknown table '{table}'"}
        return {"table": table, **info}
    return {"tables": list(SCHEMA_INFO.keys()), "details": SCHEMA_INFO}
